CREATE SCHEMA IF NOT EXISTS "public";
CREATE TABLE "User" ("id" TEXT NOT NULL,"name" TEXT,"email" TEXT NOT NULL,"passwordHash" TEXT NOT NULL,"timezone" TEXT NOT NULL DEFAULT 'UTC',"activeStart" TEXT NOT NULL DEFAULT '08:00',"activeEnd" TEXT NOT NULL DEFAULT '22:00',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "User_pkey" PRIMARY KEY ("id"));
CREATE TABLE "TelegramConnection" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"chatId" TEXT NOT NULL,"username" TEXT,"connectedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "TelegramConnection_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Reminder" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"title" TEXT NOT NULL,"mode" TEXT NOT NULL DEFAULT 'interval',"intervalMinutes" INTEGER,"fixedTime" TEXT,"active" BOOLEAN NOT NULL DEFAULT true,"nextRunAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Reminder_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ReminderJob" ("id" TEXT NOT NULL,"reminderId" TEXT NOT NULL,"userId" TEXT NOT NULL,"runAt" TIMESTAMP(3) NOT NULL,"status" TEXT NOT NULL DEFAULT 'pending',"lockedAt" TIMESTAMP(3),"attempts" INTEGER NOT NULL DEFAULT 0,CONSTRAINT "ReminderJob_pkey" PRIMARY KEY ("id"));
CREATE TABLE "DeliveryLog" ("id" TEXT NOT NULL,"reminderId" TEXT NOT NULL,"userId" TEXT NOT NULL,"jobId" TEXT,"channel" TEXT NOT NULL,"status" TEXT NOT NULL,"error" TEXT,"deliveredAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "DeliveryLog_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Account" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"type" TEXT NOT NULL,"provider" TEXT NOT NULL,"providerAccountId" TEXT NOT NULL,CONSTRAINT "Account_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Session" ("id" TEXT NOT NULL,"sessionToken" TEXT NOT NULL,"userId" TEXT NOT NULL,"expires" TIMESTAMP(3) NOT NULL,CONSTRAINT "Session_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "User_email_key" ON "User"("email"); CREATE UNIQUE INDEX "TelegramConnection_userId_key" ON "TelegramConnection"("userId"); CREATE UNIQUE INDEX "TelegramConnection_chatId_key" ON "TelegramConnection"("chatId"); CREATE INDEX "Reminder_active_nextRunAt_idx" ON "Reminder"("active","nextRunAt"); CREATE INDEX "ReminderJob_status_runAt_idx" ON "ReminderJob"("status","runAt"); CREATE UNIQUE INDEX "ReminderJob_reminderId_runAt_key" ON "ReminderJob"("reminderId","runAt"); CREATE INDEX "DeliveryLog_reminderId_deliveredAt_idx" ON "DeliveryLog"("reminderId","deliveredAt"); CREATE UNIQUE INDEX "Account_provider_providerAccountId_key" ON "Account"("provider","providerAccountId"); CREATE UNIQUE INDEX "Session_sessionToken_key" ON "Session"("sessionToken");
ALTER TABLE "TelegramConnection" ADD CONSTRAINT "TelegramConnection_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "Reminder" ADD CONSTRAINT "Reminder_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "ReminderJob" ADD CONSTRAINT "ReminderJob_reminderId_fkey" FOREIGN KEY ("reminderId") REFERENCES "Reminder"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "ReminderJob" ADD CONSTRAINT "ReminderJob_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "DeliveryLog" ADD CONSTRAINT "DeliveryLog_reminderId_fkey" FOREIGN KEY ("reminderId") REFERENCES "Reminder"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "DeliveryLog" ADD CONSTRAINT "DeliveryLog_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "Account" ADD CONSTRAINT "Account_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "Session" ADD CONSTRAINT "Session_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
